// Regenerates src/countries/index.ts from the country files present.
// Each src/countries/<alpha2>.ts must `export const documents: DocumentSpec[]`.
// Imports are aliased `<cc>_` because some codes (do, in, is) are JS keywords.
import { readdirSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const dir = fileURLToPath(new URL("../src/countries/", import.meta.url));
const codes = readdirSync(dir)
  .filter((f) => /^[a-z]{2}\.ts$/.test(f))
  .map((f) => f.slice(0, 2))
  .sort();
const lines = [
  "// GENERATED by scripts/gen-index.mjs. Do not edit; run `pnpm gen`.",
  'import type { DocumentSpec } from "../core/types.js";',
  ...codes.map((c) => `import { documents as ${c}_ } from "./${c}.js";`),
  "",
  "export const ALL_DOCUMENTS: readonly DocumentSpec[] = [",
  ...codes.map((c) => `  ...${c}_,`),
  "];",
  "",
];
writeFileSync(dir + "index.ts", lines.join("\n"));
console.log(`src/countries/index.ts: ${codes.length} countries`);
